<?php use App\Services\LlmProtocol; $llmProfiles=App\Models\LlmProfile::all(); ?>
<section class="panel llm-settings" id="llm"><div class="panel-header"><div><span class="eyebrow">UN COUP DE MAIN</span><h2>Intelligence artificielle</h2><p>Vos fournisseurs et modèles, au même endroit.</p></div><button class="button primary" type="button" data-llm-new><?= icon('plus') ?>Ajouter un fournisseur</button></div>
<p class="help-text">Plusieurs profils peuvent être enregistrés, y compris pour un même fournisseur. Un seul profil par défaut alimente les aides de l’espace. Les clés sont chiffrées et ne sont jamais réaffichées. Aucun ticket n’est envoyé automatiquement.</p>
<div class="llm-profiles"><?php foreach($llmProfiles as $profile): ?><article class="llm-profile"><header><div><h3><?= e($profile['name']) ?></h3><p><?= e(LlmProtocol::PROVIDERS[$profile['provider']]['name']??$profile['provider']) ?> · <?= e($profile['model']) ?></p></div><span class="pill <?= $profile['is_default']?'soft':'neutral' ?>"><?= $profile['is_default']?'Par défaut':($profile['enabled']?'Disponible':'Désactivé') ?></span></header><p class="llm-endpoint"><?= e($profile['base_url']) ?></p><small>Connexion vérifiée : <?= e($profile['verified_at']) ?> · Dernier usage réussi : <?= e($profile['last_used_at']??'Aucun') ?> (UTC)</small><div class="llm-actions"><button type="button" class="button subtle small-button" data-llm-edit="<?= (int)$profile['id'] ?>">Configurer</button><?php if(!$profile['is_default']): ?><form action="/llm/profiles/<?= (int)$profile['id'] ?>/action" method="post"><?= csrf() ?><input type="hidden" name="_return" value="/settings#llm"><input type="hidden" name="version" value="<?= (int)$profile['version'] ?>"><input type="hidden" name="action" value="default"><button class="button subtle small-button">Utiliser par défaut</button></form><?php endif; ?><?php if($profile['enabled']): ?><form action="/llm/profiles/<?= (int)$profile['id'] ?>/action" method="post"><?= csrf() ?><input type="hidden" name="_return" value="/settings#llm"><input type="hidden" name="version" value="<?= (int)$profile['version'] ?>"><input type="hidden" name="action" value="disable"><button class="text-button">Désactiver</button></form><?php endif; ?><form action="/llm/profiles/<?= (int)$profile['id'] ?>/action" method="post"><?= csrf() ?><input type="hidden" name="_return" value="/settings#llm"><input type="hidden" name="version" value="<?= (int)$profile['version'] ?>"><input type="hidden" name="action" value="delete"><button class="text-button danger" data-confirm="Supprimer ce profil LLM et sa clé enregistrée ?">Supprimer</button></form></div></article><?php endforeach; ?></div>
<?php if(!$llmProfiles): ?><p class="muted">Aucun fournisseur configuré. Ajoutez un profil, testez la connexion et choisissez son modèle.</p><?php endif; ?>
<p class="help-text">LM Studio et Ollama doivent être accessibles depuis le serveur PHP. En production, « localhost » désigne le serveur de l’application. Les fournisseurs distants reçoivent les textes envoyés par les utilisateurs ; leurs quotas et tarifs s’appliquent.</p></section>
<script type="application/json" id="llm-profile-data"><?= json_encode(['providers'=>LlmProtocol::PROVIDERS,'profiles'=>$llmProfiles],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script>
<dialog id="llm-config-dialog" class="dialog compact"><form class="stack" data-llm-config><header class="dialog-header"><h2>Configurer un fournisseur LLM</h2><button class="icon-button" type="button" data-close aria-label="Fermer"><?= icon('close') ?></button></header><label>Nom du profil<input name="name" required maxlength="120" placeholder="Ex. : Assistant local"></label><label>Fournisseur<select name="provider"><?php foreach(LlmProtocol::PROVIDERS as $key=>$provider): ?><option value="<?= e($key) ?>"><?= e($provider['name']) ?></option><?php endforeach; ?></select></label><label>URL de base de l’API<input type="url" name="base_url" required maxlength="500" autocomplete="off"><small data-llm-url-help></small></label><label>Clé API / jeton<input type="password" name="token" maxlength="4096" autocomplete="new-password" spellcheck="false"><small data-llm-key-help></small></label><button class="button subtle" type="button" data-llm-test>Tester la connexion et lister les modèles</button><p class="help-text" role="status" aria-live="polite" data-llm-status></p><label>Modèle<select name="model" disabled required><option value="">Testez la connexion d’abord</option></select><small>Le test vérifie le catalogue accessible. La génération dépend aussi des capacités du modèle et du quota disponible.</small></label><label class="check-label"><input type="checkbox" name="enabled" value="1" checked>Profil activé</label><label class="check-label"><input type="checkbox" name="make_default" value="1">Utiliser ce profil par défaut pour l’espace</label><button class="button primary" data-llm-save disabled>Enregistrer le profil</button></form></dialog>
